#define main oldmain
#include "power_plane.cpp"
#undef main
int main(){Plane P(4);int n=P.nb.size(),k=6;vector<ull> good;unordered_map<ull,int> idx;auto rec=[&](auto&&self,int from,int left,ull m)->void{if(!left){if(P.rounds(m)){idx[m]=good.size();good.push_back(m);}return;}for(int x=from;x<=n-left;x++)self(self,x+1,left-1,m|(1ULL<<x));};rec(rec,0,k,0);vector<int> p(good.size());iota(p.begin(),p.end(),0);auto root=[&](int x){while(x!=p[x]){p[x]=p[p[x]];x=p[x];}return x;};uint64_t E=0;map<int,int> degs;map<pair<int,int>,long long> frozen;for(int i=0;i<(int)good.size();i++){ull m=good[i];int d=0;for(ull y=m;y;y&=y-1){int v=__builtin_ctzll(y);ull avail=P.nb[v]&~m;for(ull z=avail;z;z&=z-1){int w=__builtin_ctzll(z);ull t=m^(1ULL<<v)^(1ULL<<w);auto it=idx.find(t);if(it==idx.end())continue;d++;if(it->second>i){E++;auto a=root(i),b=root(it->second);if(a!=b)p[a]=b;}}}degs[d]++;if(d==0){int a=__builtin_popcountll(m&((1ULL<<P.N)-1));frozen[{a,P.rounds(m)}]++;}}map<int,int> cs;for(int i=0;i<(int)good.size();i++)cs[root(i)]++;map<int,int> sizes;for(auto x:cs)sizes[x.second]++;cout<<"TS vertices "<<good.size()<<" edges "<<E<<" components "<<cs.size()<<"\n";for(auto [a,b]:sizes)cout<<"size "<<a<<" count "<<b<<"\n";for(auto [a,b]:degs)cout<<"degree "<<a<<" count "<<b<<"\n";for(auto [a,b]:frozen)cout<<"frozen_balance_time "<<a.first<<" "<<a.second<<" count "<<b<<"\n";}
